#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> stones(n);
    for (int i = 0; i < n; i++) cin >> stones[i];

    unordered_map<int, unordered_set<int>> dp;

    dp[0].insert(0); // starting point

    for (int i = 0; i < n; i++) {
        int stone = stones[i];

        for (int jump : dp[stone]) {

            for (int nextJump = jump - 1; nextJump <= jump + 1; nextJump++) {

                if (nextJump > 0) {
                    int nextStone = stone + nextJump;

                    if (dp.find(nextStone) != dp.end()) {
                        dp[nextStone].insert(nextJump);
                    }
                }
            }
        }
    }

    if (!dp[stones[n - 1]].empty())
        cout << "true";
    else
        cout << "false";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool solve(int n, vector<int>& stones, vector<vector<int>>& dp, int ind, int k) {
    if (ind == n - 1) return true;
    if (k == 0) return false;

    if (dp[ind][k] != -1) return dp[ind][k];

    bool ans = false;

    for (int i = -1; i <= 1; i++) {
        int nextJump = k + i;
        if (nextJump <= 0) continue;

        int target = stones[ind] + nextJump;

        int l = ind + 1, r = n - 1;
        while (l <= r) {
            int mid = (l + r) / 2;

            if (stones[mid] == target) {
                ans = ans || solve(n, stones, dp, mid, nextJump);
                break;
            }
            else if (stones[mid] < target) {
                l = mid + 1;
            }
            else {
                r = mid - 1;
            }
        }
    }

    return dp[ind][k] = ans;
}

int main() {
    int n;
    cin >> n;

    vector<int> stones(n);
    for (int i = 0; i < n; i++) {
        cin >> stones[i];
    }

    if (n < 2 || stones[1] - stones[0] > 1) {
        cout << "false";
        return 0;
    }

    vector<vector<int>> dp(n, vector<int>(n, -1));

    bool result = solve(n, stones, dp, 1, 1);

    if (result) cout << "true";
    else cout << "false";

    return 0;
}

